package provider

import (
	"context"
	"time"

	"github.com/ER-brocode/vault-broker-core/pkg/lease"
)

// CredentialType identifies the cloud or database credential family.
type CredentialType string

const (
	TypeAWSIAM       CredentialType = "AWS_IAM"
	TypeGCPSA        CredentialType = "GCP_SERVICE_ACCOUNT"
	TypePostgres     CredentialType = "DATABASE_POSTGRES"
	TypeMySQL        CredentialType = "DATABASE_MYSQL"
)

// TemporaryCredentials represents dynamic short-lived credentials generated by providers.
type TemporaryCredentials struct {
	Type        CredentialType    `json:"type"`
	IssuedTo    string            `json:"issued_to"`
	Attributes  map[string]string `json:"attributes"`
	TTL         time.Duration     `json:"ttl"`
	MaxTTL      time.Duration     `json:"max_ttl"`
	CreatedAt   time.Time         `json:"created_at"`
	ExpiresAt   time.Time         `json:"expires_at"`
	Metadata    map[string]string `json:"metadata,omitempty"`
}

// DynamicCredentialProvider defines the interface required for all cloud and database credential engines.
type DynamicCredentialProvider interface {
	Name() string
	Type() CredentialType
	Generate(ctx context.Context, req Request) (*TemporaryCredentials, lease.RevokeFunc, lease.RotateFunc, error)
}

// Request holds standard parameters used when requesting ephemeral credentials.
type Request struct {
	Identity     string            `json:"identity"`     // SPIFFE ID or caller identity
	RoleOrScope  string            `json:"role_or_scope"` // Target IAM role, scope, or DB role
	TTL          time.Duration     `json:"ttl"`
	MaxTTL       time.Duration     `json:"max_ttl"`
	PolicyTags   map[string]string `json:"policy_tags,omitempty"`
}
